// 纯函数选择器。
//
// 刻意与 `store.svelte.ts` 分开: 这里全部是**普通函数**, 不碰任何 rune, 因此可以直接在 node
// 环境的单测里调用, 也可以作为组件里 `$derived` 的计算体。

import type { OpenDocument } from './store.svelte';
import type { ConfigTab, ResourceTab, SceneTab, WorkbenchTabItem } from '../tabs/model';

/** 选择器只需要读这些字段, 因此不要求完整的 store 形状 —— 便于单测构造最小输入。 */
export interface SelectorState {
  tabs: WorkbenchTabItem[];
  activeTabId: string | null;
  documents: OpenDocument[];
}

/**
 * 配音工作台是否打开。
 *
 * 它就是一个普通选项卡, 因此**不设独立开关**: 由选项卡是否存在于序列中推导, 从根上避免
 * "开关与选项卡状态不一致"这类问题。
 */
export function isVoiceWorkbenchOpen(tabs: WorkbenchTabItem[]): boolean {
  return tabs.some((tab) => tab.kind === 'voice-workbench');
}

/** 配音工作台选项卡是否处于激活状态 */
export function isVoiceWorkbenchActive(state: SelectorState): boolean {
  return state.tabs.find((tab) => tab.id === state.activeTabId)?.kind === 'voice-workbench';
}

/**
 * 某个场景卡的麦克风开关是否应当显示 —— 配音编辑模式**唯一**的可见性规则:
 *
 * * 配音工作台未打开 -> 一律不显示 (未启用配音功能时界面上不出现任何配音痕迹);
 * * 已处于配音编辑模式 -> 始终显示 (否则就没法退出);
 * * 未处于配音编辑模式 -> 只在**当前选中的**那张卡上显示 (`activeTabId`, 而不是"最近的场景卡":
 *   切到工作台/说明页之后, 划线麦克风不该继续挂在原来那张卡上)。
 */
export function shouldShowVoiceToggle(input: {
  /** 配音工作台是否打开 */
  workbenchOpen: boolean;
  /** 当前活动的选项卡 id */
  activeTabId: string | null;
  /** 要判断的选项卡 */
  tab: WorkbenchTabItem;
  /** 处于配音编辑模式的场景路径 */
  voiceModePaths: string[];
}): boolean {
  const { workbenchOpen, activeTabId, tab, voiceModePaths } = input;
  if (!workbenchOpen || tab.kind !== 'scene') return false;
  return voiceModePaths.includes(tab.path) || tab.id === activeTabId;
}

/** 当前活动选项卡 */
export function activeTabOf(state: SelectorState): WorkbenchTabItem | null {
  return state.tabs.find((tab) => tab.id === state.activeTabId) ?? null;
}

/** 当前活动的场景/文件选项卡 */
export function activeSceneTabOf(state: SelectorState): SceneTab | null {
  const tab = activeTabOf(state);
  return tab?.kind === 'scene' ? tab : null;
}

/** 当前活动的场景文档 */
export function activeSceneDocumentOf(state: SelectorState): OpenDocument | null {
  const tab = activeSceneTabOf(state);
  if (!tab) return null;
  return state.documents.find((doc) => doc.path === tab.path) ?? null;
}

/** 当前活动的资源选项卡。 */
export function activeResourceTabOf(state: SelectorState): ResourceTab | null {
  const tab = activeTabOf(state);
  return tab?.kind === 'resource' ? tab : null;
}

/** 当前活动的文本资源文档。 */
export function activeResourceDocumentOf(state: SelectorState): OpenDocument | null {
  const tab = activeResourceTabOf(state);
  if (!tab || tab.resourceKind !== 'text') return null;
  return state.documents.find((doc) => doc.path === tab.path) ?? null;
}

/** 当前活动的配置选项卡 (`game/config.txt`)。 */
export function activeConfigTabOf(state: SelectorState): ConfigTab | null {
  const tab = activeTabOf(state);
  return tab?.kind === 'config' ? tab : null;
}

/** 当前活动的配置文档。 */
export function activeConfigDocumentOf(state: SelectorState): OpenDocument | null {
  const tab = activeConfigTabOf(state);
  return tab ? (state.documents.find((doc) => doc.path === tab.path) ?? null) : null;
}

/** 项目内是否存在任何选项卡 */
export function hasTabs(tabs: WorkbenchTabItem[]): boolean {
  return tabs.length > 0;
}
